+     * <pre>
+     *     <code>
+     *         {
+     *           "predictions": [
+     *              {
+     *                "embeddings": {
+     *                  "statistics": {
+     *                    "truncated": false,
+     *                    "token_count": 6
+     *                  },
+     *                  "values": [ ... ]
+     *                }
+     *              }
+     *           ]
+     *         }
+     *     </code>
+     * </pre>
